  // Seeds 68030000 through 6803000f.
  function automatic logic [7:0] m6805_program_byte(
    input logic [7:0] program_index, input logic [7:0] byte_index
  );
    begin
      m6805_program_byte = 8'h00;
      case ({program_index, byte_index})
        16'h0000: m6805_program_byte = 8'hab;
        16'h0001: m6805_program_byte = 8'h78;
        16'h0002: m6805_program_byte = 8'ha6;
        16'h0003: m6805_program_byte = 8'h6e;
        16'h0004: m6805_program_byte = 8'h44;
        16'h0005: m6805_program_byte = 8'hae;
