        16'h0007: m6805_program_byte = 8'hab;
        16'h0008: m6805_program_byte = 8'hcb;
        16'h0009: m6805_program_byte = 8'h59;
        16'h000a: m6805_program_byte = 8'h46;
        16'h000b: m6805_program_byte = 8'h53;
        16'h000c: m6805_program_byte = 8'ha5;
        16'h000d: m6805_program_byte = 8'ha2;
        16'h000e: m6805_program_byte = 8'h9f;
        16'h000f: m6805_program_byte = 8'h58;
        16'h0010: m6805_program_byte = 8'h50;
        16'h0011: m6805_program_byte = 8'ha3;
